package edu.pe.cibertec.saibm.inventario.application.usecase; import java.time.*; import java.util.*; import edu.pe.cibertec.saibm.inventario.application.port.in.InventoryUseCase; import edu.pe.cibertec.saibm.inventario.application.port.out.InventoryStorePort; import edu.pe.cibertec.saibm.inventario.domain.event.InventoryEvent; import edu.pe.cibertec.saibm.inventario.domain.exception.InventoryConflictException; import edu.pe.cibertec.saibm.inventario.domain.model.*; import edu.pe.cibertec.saibm.inventario.domain.service.*; public class InventoryService implements InventoryUseCase {private final InventoryStorePort store;private final RequestHasher hasher=new RequestHasher();private final InventoryStateMachine machine=new InventoryStateMachine();public InventoryService(InventoryStorePort s){store=s;} public Outcome hold(String b,int q,Instant e,String k,String c){if(b==null||b.isBlank()||q<1||e==null||k==null||k.isBlank())throw new InventoryConflictException("Invalid hold request");String h=hasher.hold(b,q,e.toString());var old=store.holdForUpdate(k);if(old.isPresent())return replay(old.get(),h,b);var hold=Hold.held(UUID.randomUUID(),k,b,q,e,h);if(!store.insert(hold))return replay(store.holdForUpdate(k).orElseThrow(),h,b);var stock=store.stockForUpdate(b).orElseThrow(()->new InventoryConflictException("Inventory not found"));if(!stock.reserve(q)){hold.reject();store.save(hold);emit(hold,"InventoryRejected",c);return outcome(hold,false);}store.save(stock);store.save(hold);store.movement(new InventoryMovement(UUID.randomUUID(),b,-q,"HOLD",k,Instant.now()));emit(hold,"InventoryHeld",c);return outcome(hold,true);} public Outcome commit(String b,String k,String c){return transition(b,k,InventoryOperation.COMMIT,"InventoryCommitted",c);} public Outcome release(String b,String k,String c){return transition(b,k,InventoryOperation.RELEASE,"InventoryReleased",c);} private Outcome transition(String b,String k,InventoryOperation op,String type,String c){Hold h=store.holdForUpdate(k).orElseThrow(()->new InventoryConflictException("Inventory operation not found"));if(!h.bookId().equals(b))throw new InventoryConflictException("Operation book mismatch");InventoryState finalState=op==InventoryOperation.COMMIT?InventoryState.COMMITTED:InventoryState.RELEASED;if(h.state()==finalState||h.state()==InventoryState.EXPIRED)return outcome(h,true);InventoryState next=machine.transition(h.state(),op,h.expiresAt(),Instant.now());if(next==InventoryState.RELEASED||next==InventoryState.EXPIRED){var s=store.stockForUpdate(b).orElseThrow();s.release(h.quantity());store.save(s);store.movement(new InventoryMovement(UUID.randomUUID(),b,h.quantity(),"RELEASE",k,Instant.now()));}h.transition(next);store.save(h);emit(h,type,c);return outcome(h,true);} private Outcome replay(Hold h,String hash,String b){if(!h.bookId().equals(b)||!h.requestHash().equals(hash))throw new InventoryConflictException("Idempotency key was reused with a different payload");return outcome(h,h.state()!=InventoryState.REJECTED);}private Outcome outcome(Hold h,boolean a){return new Outcome(new View(h.operationKey(),h.bookId(),h.quantity(),h.state(),h.expiresAt()),a);}private void emit(Hold h,String type,String c){var p=Map.<String,Object>of("bookId",h.bookId(),"operationKey",h.operationKey(),"quantity",h.quantity(),"expiresAt",h.expiresAt().toString(),"state",h.state().name());store.outbox(new InventoryEvent(UUID.randomUUID(),type+".v1",1,Instant.now(),c==null?"":c,h.operationKey(),"inventario-service",p));}}
